fn numpy_append(mut arr: Vec<f32>, values: Vec<f32>) -> Vec<f32> {
    // Pre-allocate enough space for both vectors to avoid
    // unnecessary reallocations.
    arr.reserve(values.len());
    // Extend `arr` in-place by consuming all elements from `values`.
    arr.extend(values);
    // `arr` now contains its original elements followed by all elements of `values`.
    arr
}

